struct TickObservation {
    study_round::Step step = study_round::Step::waiting;
    int kick = -1;
    std::optional<LockReport> lock;
};

struct FrameReport {
    unsigned ticks = 0;
    bool clamped = false;
    bool board_changed = false;
    bool piece_changed = false;
    int cleared = 0;
    std::array<TickObservation, max_ticks> observations{};
};

static std::optional<Batch> from(
        const study_loop::FrameReport& report) noexcept {
        if (report.ticks > report.observations.size()) return std::nullopt;

        Batch batch;
        for (unsigned i = 0; i < report.ticks; ++i) {
            const study_loop::TickObservation& observation =
                report.observations[i];
            if (observation.step == study_round::Step::stopped ||
                observation.step == study_round::Step::invalid) {
                continue;
            }
            if (observation.kick >= 0) batch.append(Kind::rotate);
            if (observation.lock.has_value()) {
                if (observation.lock->hard_drop_distance >= 0)
                    batch.append(Kind::drop);
                if (observation.lock->cleared > 0) batch.append(Kind::clear);
                if (observation.lock->inserted > 0)
                    batch.append(Kind::garbage);
            }
        }
        return std::optional<Batch>(std::move(batch));
    }

std::optional<Kind> take() noexcept {
        if (next_ >= size_) return std::nullopt;
        const Kind kind = kinds_[next_];
        ++next_;
        return kind;
    }

void move_from(Batch& other) noexcept {
        kinds_ = other.kinds_;
        size_ = other.size_;
        next_ = other.next_;
        other.clear();
    }

inline std::optional<Pcm16> make_cue(study_sound::Kind kind) {
    constexpr std::uint32_t kRate = 44100;
    constexpr std::uint32_t kChannels = 2;
    constexpr std::size_t kFrames = 4410;
    constexpr std::size_t kEnvelope = 441;
    constexpr int kPeak = 2000;
    constexpr int kPeriods[] = {100, 200, 64, 320};

    const int index = static_cast<int>(kind);
    if (index < 0 || index >= 4) return std::nullopt;

    const int period = kPeriods[index];
    const int quarter = period / 4;

    std::vector<std::int16_t> samples;
    samples.reserve(kFrames * kChannels);

    for (std::size_t n = 0; n < kFrames; ++n) {
        const int phase =
            static_cast<int>(n % static_cast<std::size_t>(period));
        int ramp;
        if (phase < quarter) {
            ramp = phase;
        } else if (phase < 3 * quarter) {
            ramp = period / 2 - phase;
        } else {
            ramp = phase - period;
        }

        const std::size_t tail = kFrames - 1 - n;
        const int envelope =
            static_cast<int>(std::min(n, std::min(tail, kEnvelope)));
        const int sample =
            (ramp * kPeak / quarter) * envelope / static_cast<int>(kEnvelope);

        const auto value = static_cast<std::int16_t>(sample);
        samples.push_back(value);  // left
        samples.push_back(value);  // right
    }

    return Pcm16::make(kRate, kChannels, std::move(samples));
}

bool Player::replace(Pcm16&& clip, std::size_t slot) noexcept {
    // Closed takes priority over an out-of-range slot.
    if (dev_ == 0) return false;
    if (slot >= kSlots) return false;
    // Validate before touching the old clip so a failed call preserves it.
    if (clip.layout().frames == 0) return false;
    if (clip.rate() != rate_ || clip.channels() != channels_) return false;
    if (!audio_pcm::layout_s16(1, clip.channels(), clip.rate()).has_value())
        return false;

    // Transfer ownership under the lock; free the old PCM after unlocking.
    // Only the targeted mixer slot is stopped, so other slots keep playing.
    // Pcm16 moves without allocation or exceptions.
    std::optional<Pcm16> retired;
    {
        DeviceLock lock(dev_);
        mixer_.stop(slot);
        retired.swap(clips_[slot]);           // displace old PCM under the lock
        clips_[slot].emplace(std::move(clip)); // install new PCM under the lock
    }
    return true;  // `retired` destructs here, after unlock
}

void Player::unload(std::size_t slot) noexcept {
    if (dev_ == 0) return;
    if (slot >= kSlots) return;
    // No global pause: the other slots must keep playing while this one is
    // retired. Only the targeted mixer slot is stopped.

    // Retired outside the lock scope: the old PCM buffer is destroyed only
    // after DeviceLock runs SDL_UnlockAudioDevice.
    std::optional<Pcm16> retired;
    {
        DeviceLock lock(dev_);
        mixer_.stop(slot);
        retired.swap(clips_[slot]);
    }
    // `retired` destructs here, i.e. the old PCM deallocation happens post-unlock.
}

bool Player::play(std::size_t slot) noexcept {
    // Closed takes priority over an out-of-range slot.
    if (dev_ == 0) return false;
    if (slot >= kSlots) return false;
    if (!clips_[slot].has_value()) return false;

    bool started = false;
    {
        DeviceLock lock(dev_);
        started = mixer_.start(slot, *clips_[slot]);
    }
    // Unpause only after the lock is released.
    SDL_PauseAudioDevice(dev_, 0);
    return started;
}

const auto update = app.advance(frame.dt, raw, confirm,
                                platform_key_pressed(Key::Escape), released);
if (!update) return 1;
if (update->game_replaced || app.screen() == study_app::Screen::menu ||
    app.screen() == study_app::Screen::quitting) sound.stop();
if (update->frame) {
    auto sounds = study_sound::Batch::from(*update->frame);
    if (!sounds) return 1;
    while (const auto kind = sounds->take()) (void)sound.play(*kind);
}
if (app.screen() == study_app::Screen::quitting) break;

void Game::ConsumeSoundEvents()
{
    // Detach every pending request before calling the presentation backend.
    // A bool coalesces same-kind occurrences within one simulation call.
    const bool rotate = std::exchange(sim.rotateSoundEvent, false);
    const bool drop = std::exchange(sim.dropSoundEvent, false);
    const bool clear = std::exchange(sim.clearSoundEvent, false);
    const bool garbage = std::exchange(sim.garbageSoundEvent, false);
    if (rotate) audio_play_sound(sndRotate);
    // Choose a fallback at playback time; each handle keeps unique ownership.
    if (drop) audio_play_sound(sndDrop ? sndDrop : sndRotate);
    if (clear) audio_play_sound(sndClear);
    if (garbage) audio_play_sound(sndGarbage ? sndGarbage : sndClear);
}
